pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v) internal {
        bool setReverted;
        try c.SetMinSum(v) { setReverted = false; } catch { setReverted = true; }
        uint256 afterSet;
        try c.MinSum() returns (uint256 __r) { afterSet = __r; } catch { return; }
        uint256 balBefore = address(c).balance;
        bool initReverted;
        try c.Initialized() { initReverted = false; } catch { initReverted = true; }
        uint256 balAfter = address(c).balance;
        uint256 afterInit;
        try c.MinSum() returns (uint256 __r) { afterInit = __r; } catch { return; }
        assertTrue(!setReverted && afterSet == v && afterInit == v && balBefore == balAfter);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
